 const definitions={en:{pass:'A pass sends the ball to a teammate.',shot:'A shot is an attempt to score a goal.',tackle:'A recovery means winning the ball back.'},es:{pass:'Un pase envía el balón a un compañero.',shot:'Un disparo es un intento de marcar un gol.',tackle:'Una recuperación significa volver a ganar el balón.'},pt:{pass:'Um passe envia a bola a um companheiro.',shot:'Um chute é uma tentativa de marcar um gol.',tackle:'Uma recuperação significa ganhar a bola de volta.'}},guideDefinition=definitions[language][last?.outcome==='intercepted'?'tackle':last?.type||'pass'];
